mapper.select:
SELECT job_id FROM adhoc_query_job j
WHERE j.status='PENDING' AND j.is_deleted=0 AND j.cancel_requested=0
  AND j.submit_time > DATE_SUB(NOW(), INTERVAL #{recentWindowHours} HOUR)
  AND (SELECT COUNT(*) FROM adhoc_query_job WHERE status IN ('DISPATCHING','RUNNING')) < #{maxRunningGlobal}
  AND (SELECT COUNT(*) FROM adhoc_query_job WHERE status IN ('DISPATCHING','RUNNING') AND user_id=j.user_id) < #{maxRunningPerUser}
  AND (SELECT COUNT(*) FROM adhoc_query_job WHERE processing_server_instance=#{serverInstance}
       AND status IN ('DISPATCHING','RUNNING')) < #{maxRunningPerServer}
  AND EXISTS (
    SELECT 1 FROM adhoc_executor_instance e
    WHERE e.status='UP' AND e.accepting=1
      AND FIND_IN_SET(j.engine_type, e.engine_types)
      AND IFNULL(JSON_LENGTH(e.running_tasks), 0) < e.max_concurrent_tasks
  )
  AND EXISTS (
    SELECT 1 FROM adhoc_server_instance s
    WHERE s.instance_id=#{serverInstance} AND s.accepting=1
  )
ORDER BY j.submit_time ASC LIMIT 1

SELECT job_id AS jobId, user_id AS userId, user_name AS userName,
       engine_type AS engineType, status AS status,
       submit_time AS submitTime, start_time AS startTime, finish_time AS finishTime,
       COALESCE(duration_ms, TIMESTAMPDIFF(MICROSECOND, submit_time, finish_time) DIV 1000) AS durationMs,
       executor_instance AS executorInstance
FROM adhoc_query_job
WHERE is_deleted = 0
  AND submit_time >= #{startTime} AND submit_time <= #{endTime}
  AND status = #{status}
  AND engine_type = #{engineType}
  AND COALESCE(duration_ms, TIMESTAMPDIFF(MICROSECOND, submit_time, finish_time) DIV 1000) >= #{minDurationMs}
  AND COALESCE(duration_ms, TIMESTAMPDIFF(MICROSECOND, submit_time, finish_time) DIV 1000) <  #{maxDurationMs}

      ORDER BY COALESCE(duration_ms, TIMESTAMPDIFF(MICROSECOND, submit_time, finish_time) DIV 1000) DESC, submit_time DESC
      ORDER BY COALESCE(duration_ms, TIMESTAMPDIFF(MICROSECOND, submit_time, finish_time) DIV 1000) ASC, submit_time DESC
      ORDER BY submit_time ASC
      ORDER BY submit_time DESC
